// Adapter scaffold generated by @hexagen/sync — implemented for lane FS3a-B.
/**
 * AllowedSeatAdapter implements AllowedSeatPort: decide whether a dispatch seat
 * (tool, model, variant) or a reviewer model may be used under the
 * installation's free-seat policy. The input is a structural subset of
 * `@fleet/installation`'s seat catalogue, so this module keeps work-execution
 * free of a dependency on that package.
 *
 * With `policy.useFreeSeats` absent or `true` every seat is allowed. With the
 * flag `false` only seats that are all not free are allowed; an unknown triple
 * or model is refused (fail closed), as is a match that touches any free seat.
 * Seats that differ only in `agent` are the same triple.
 */

import type {
  AllowedSeatCatalogueSeat,
  AllowedSeatPort,
  AllowedSeatVerdict,
  DispatchSeatQuery,
  ReviewerModelQuery,
} from '../../application/ports/out/AllowedSeatPort.out-port.js';

export type { AllowedSeatCatalogueSeat };

export interface AllowedSeatAdapterOptions {
  /**
   * The installation's seat catalogue. Absent means no seats are known: with
   * the flag off every dispatch or review is refused as not in the catalogue.
   */
  readonly seats?: readonly AllowedSeatCatalogueSeat[];
  /**
   * The installation's policy. Absent or `useFreeSeats: true` keeps today's
   * behaviour: every seat is allowed.
   */
  readonly policy?: { readonly useFreeSeats?: boolean };
}

/** Normalise a variant for equality: absent, null or blank is "none". */
function normaliseVariant(variant: string | null | undefined): string {
  const trimmed = variant?.trim() ?? '';
  return trimmed === '' ? 'none' : trimmed;
}

export class AllowedSeatAdapter implements AllowedSeatPort {
  constructor(private readonly options?: AllowedSeatAdapterOptions) {}

  checkDispatchSeat(query: DispatchSeatQuery): AllowedSeatVerdict {
    if (this.options?.policy?.useFreeSeats !== false) {
      return { allowed: true, useFreeSeats: true };
    }
    const queryVariant = normaliseVariant(query.variant);
    const matches = (this.options?.seats ?? []).filter(
      (seat) =>
        seat.tool === query.tool &&
        seat.model === query.model &&
        normaliseVariant(seat.variant) === queryVariant,
    );
    const subject = `Seat (tool ${query.tool}, model ${query.model}, variant ${query.variant ?? 'none'})`;
    return this.verdictForMatches(subject, matches);
  }

  checkReviewerModel(query: ReviewerModelQuery): AllowedSeatVerdict {
    if (this.options?.policy?.useFreeSeats !== false) {
      return { allowed: true, useFreeSeats: true };
    }
    const matches = (this.options?.seats ?? []).filter(
      (seat) =>
        seat.model === query.model ||
        (seat.variant !== undefined && `${seat.model}:${seat.variant}` === query.model),
    );
    const subject = `Reviewer model ${query.model}`;
    return this.verdictForMatches(subject, matches);
  }

  private verdictForMatches(
    subject: string,
    matches: readonly AllowedSeatCatalogueSeat[],
  ): AllowedSeatVerdict {
    if (matches.length === 0) {
      return {
        allowed: false,
        useFreeSeats: false,
        reason: `${subject} is not in the installation's seat catalogue; policy.useFreeSeats is false, so only a catalogue seat that is not free may run`,
      };
    }
    const ids = matches.map((seat) => seat.id).join(', ');
    const freeCount = matches.filter((seat) => seat.costClass === 'free').length;
    if (freeCount === matches.length) {
      return {
        allowed: false,
        useFreeSeats: false,
        reason: `${subject} is a free seat (${ids}); policy.useFreeSeats is false`,
      };
    }
    if (freeCount > 0) {
      return {
        allowed: false,
        useFreeSeats: false,
        reason: `${subject} matches catalogue seats of mixed cost class (${ids}); policy.useFreeSeats is false, so the ambiguous match is refused`,
      };
    }
    return { allowed: true, useFreeSeats: false };
  }
}
